import {BEAT,BIOMES,CRYSTALS,SKILLS,SEALS,createState,restoreState,startRun,finishRun,act,tick,descend,biomeIndex,depthLimit,maxRhythm,windowMs,power,upgradeCost,coreCost,purchaseUpgrade,purchaseCore,purchaseSeal,canLearn,learn,equip,distance} from './core.js';
import {World,project,unproject,HOTSPOTS} from './world.js';
import {Music} from './audio.js';
const $=id=>document.getElementById(id),KEY='gemventure-save-v2';
let s;try{s=restoreState(localStorage.getItem(KEY))||restoreState(localStorage.getItem('gemventure-save-v1'));}catch{}s=s||createState();
const world=new World($('world')),music=new Music();let elapsed=s.run?.elapsed||0,lastFrame=performance.now(),paused=!!s.run,hidden=document.hidden,selected=null,hover=null,dialogKind='',skillSelected='ear',toastTimer,baseTimer,feedbackTimer=0;world.place(s);
const blocked=()=>paused||hidden||$('dialog').open;
const fmt=n=>new Intl.NumberFormat('pt-BR').format(n);
function save(){if(s.run)s.run.elapsed=elapsed;try{localStorage.setItem(KEY,JSON.stringify(s));$('saved').textContent='SALVO LOCALMENTE';}catch{$('saved').textContent='SALVAMENTO INDISPONÍVEL';}}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function feedback(t){$('message').textContent=t;feedbackTimer=elapsed+2;}
function update(){const r=s.run;$('bank').textContent=fmt(s.bank);$('essence').textContent=s.essence;$('record').textContent=s.best?`${s.best*25} m`:'—';$('sceneTitle').textContent=r?BIOMES[biomeIndex(r.floor)].name:'Seu próximo passo começa aqui.';$('sceneEyebrow').textContent=r?`EXPEDIÇÃO ${String(s.attempts).padStart(2,'0')} · UMA BATIDA DE CADA VEZ`:'UM NOVO DIA, UMA NOVA DESCOBERTA';$('locationLabel').textContent=r?'CAVERNA VIVA · '+(r.room.cleared?'ESTABILIZADA':'EM EXPLORAÇÃO'):'REFÚGIO DO PRIMEIRO BRILHO';$('floorLabel').textContent=r?`ANDAR ${String(r.floor).padStart(2,'0')} / 16 · ${r.floor*25} METROS`:'SUPERFÍCIE · ZONA SEGURA';for(const id of ['runHud','objective','runControls','extract'])$(id).hidden=!r;for(const id of ['baseNote','baseLaunch','baseControls'])$(id).hidden=!!r;$('clearBanner').hidden=!r?.room.cleared;$('pauseCover').hidden=!r||!paused;
 $('slots').textContent=`${s.equipped.length} / 5`;$('equippedSlots').innerHTML=Array.from({length:5},(_,i)=>{const skill=SKILLS.find(k=>k.id===s.equipped[i]);return`<button class="skill-slot ${skill?'':'empty'}" aria-label="${skill?skill.name:'Espaço de habilidade vazio'}" title="${skill?skill.name+': '+skill.desc:'Escolha uma habilidade na árvore'}">${skill?.icon||'+'}</button>`;}).join('');$('equippedSlots').querySelectorAll('button').forEach(b=>b.onclick=()=>r?toast('Ajuste suas cinco habilidades na base.'):showTree());const seal=SEALS[s.seals];$('nextMilestone').textContent=seal?`Próximo marco: andar ${seal.floor} → ${seal.name.toLowerCase()}.`:'Todos os caminhos estão abertos. Alcance o manto.';$('footerState').textContent=r?`PICARETA NV. ${s.level} · FORÇA ${power(s)} · ${windowMs(s)} ms DE SINCRONIA`:`EXPEDIÇÕES ${s.attempts} · MELHOR SEQUÊNCIA ${s.bestCombo} · ${s.unlocked.length}/17 HABILIDADES`;
 if(r){$('hpLabel').textContent=`${Math.ceil(r.rhythm)} / ${maxRhythm(s)}`;$('hpBar').style.width=`${r.rhythm/maxRhythm(s)*100}%`;$('hpBar').style.background=r.rhythm<30?'#de523e':'#92e8c0';$('vitalHint').textContent=r.rhythm<30?'Fôlego baixo! Procure um cristal vital.':'Acertar recupera. Errar desgasta.';$('combo').innerHTML=`${r.combo}<span>×</span>`;$('comboHint').textContent=r.combo>=8?'EM FLUXO':r.combo?'Mantenha a sequência':'Encontre o pulso';$('charge').textContent=`${Math.min(r.room.charge,r.room.quota)} / ${r.room.quota}`;$('chargeBar').style.width=`${Math.min(100,r.room.charge/r.room.quota*100)}%`;$('goal').textContent=`${Math.min(r.combo,r.room.goal)} / ${r.room.goal}`;$('bagLabel').textContent=`MOCHILA · ${r.bag} GEMAS`;const canDescend=r.floor<depthLimit(s)&&r.floor<16;$('descend').hidden=!canDescend;$('clearTitle').textContent=r.floor===16?'Você encontrou o coração da Terra.':canDescend?'O caminho está aberto.':'Um novo bioma espera por você.';$('clearSubtitle').textContent=r.floor===16?'Volte à base com tudo o que conquistou.':canDescend?'Descer recupera 15 de fôlego. Voltar guarda todas as gemas.':`Volte à base e construa o ${SEALS[s.seals]?.name.toLowerCase()}.`;const width=windowMs(s)/1000/BEAT*50;$('perfectZone').style.width=width+'%';$('perfectZone').style.left=(50-width/2)+'%';}updateTip();}
function updateTip(){const r=s.run,n=r?[...r.room.nodes,...r.room.enemies].find(n=>n.id===(hover??selected)&&n.hp>0):null;$('targetTip').hidden=!n||!!r?.room.cleared;if(n){const crystal=n.type==='crystal',d=crystal?CRYSTALS[n.kind]:null;$('targetTip').innerHTML=`<strong style="color:${d?.color||'#fea7a7'}">${d?.name||['Gosma rítmica','Morcego de eco','Guardião de pedra'][n.kind]} · ${n.hp}/${n.maxHp}</strong><span>${crystal?`${d.tip}<br>◇ ${n.value} gemas base · ${d.charge} carga${d.charge>1?'s':''}`:n.windup?'ATAQUE MARCADO! Saia do chão vermelho.':'Clique para atingir. WASD para esquivar.'}</span>`;}}
function chooseNext(){const r=s.run;if(!r)return;const options=[...r.room.nodes,...r.room.enemies].filter(n=>n.hp>0).sort((a,b)=>distance(a,r.player)-distance(b,r.player));selected=options[0]?.id??null;}
function processEvents(){const r=s.run;if(!r)return;const events=r.events.splice(0);world.consume(events);for(const e of events){if(e.type==='perfect'){$('timing').textContent=`NO PULSO · sequência ${e.combo}`;feedback('PERFEITO · continue no pulso');music.hit(true);}if(e.type==='hurt'){feedback(e.reason==='attack'?`ATINGIDO · −${e.amount} fôlego`:`FORA DO RITMO · −${e.amount} fôlego`);$('timing').textContent=e.reason==='silence'?'Batida perdida. Volte ao centro.':'Respire. Uma ação por batida.';}if(e.type==='clear'){music.reward();feedback('Sala estabilizada. O elevador está pronto.');}if(e.type==='revive')toast('Última batida! Você recuperou 30 de fôlego.');}}
function perform(action){if(!s.run||blocked()||s.run.room.cleared)return;act(s,action,(elapsed+(performance.now()-lastFrame)/1000)/BEAT);if(!s.run){onReturn();return;}processEvents();if(![...s.run.room.nodes,...s.run.room.enemies].some(n=>n.id===selected&&n.hp>0))chooseNext();update();save();}
function begin(){closeDialog();if(!startRun(s))return;elapsed=0;paused=false;selected=null;chooseNext();world.place(s);music.silence();feedback('Prepare-se: siga as quatro primeiras batidas.');update();save();$('world').focus({preventScroll:true});}
function onReturn(){paused=false;elapsed=0;selected=null;hover=null;feedback('Clique em uma construção para interagir.');music.silence();world.place(s);update();save();showResult();}
function returnSafe(){finishRun(s,s.run?.floor===16&&s.run?.room.cleared?'victory':'return');onReturn();}
function nextFloor(){if(descend(s)){elapsed=0;selected=null;chooseNext();music.silence();world.place(s);feedback(`Andar ${s.run.floor}. A caverna ganhou um novo pulso.`);update();save();$('world').focus({preventScroll:true});}}
function extract(){if(!s.run)return;if(s.run.room.cleared)returnSafe();else{openDialog('RETIRADA DE EMERGÊNCIA',`<h2>Levar o que for possível.</h2><p>O elevador ainda não foi energizado. O resgate encerra esta expedição e recupera <b>metade das ${s.run.bag} gemas da mochila</b>. As melhorias da base permanecem.</p><div class="shop-items"><button class="primary" id="confirmRetreat">Resgatar ${Math.floor(s.run.bag*.5)} gemas e voltar</button><button class="secondary" id="keepGoing">Continuar na caverna</button></div>`,'retreat');$('confirmRetreat').onclick=()=>{finishRun(s,'retreat');closeDialog();onReturn();};$('keepGoing').onclick=closeDialog;}}
function openDialog(label,body,kind=''){dialogKind=kind;music.silence();$('dialogLabel').textContent=label;$('dialog').classList.toggle('tree-dialog',kind==='tree');$('dialogBody').innerHTML=body;if(!$('dialog').open)$('dialog').showModal();}
function closeDialog(){if($('dialog').open)$('dialog').close();}
$('close').onclick=closeDialog;$('dialog').addEventListener('close',()=>{dialogKind='';lastFrame=performance.now();$('world').focus({preventScroll:true});});
function showResult(){const r=s.lastResult;if(!r)return;const death=r.reason==='death';openDialog('DE VOLTA AO REFÚGIO',`<div class="result-hero"><span class="result-icon">${death?'♡':r.reason==='victory'?'✦':'◇'}</span><h2>${death?'O ritmo se foi. A jornada continua.':r.reason==='victory'?'O manto é só o começo.':'Cada retorno deixa você mais forte.'}</h2><p>${death?'Seu fôlego chegou a zero. O Jardineiro resgatou metade da mochila.':r.reason==='retreat'?'O resgate de emergência trouxe metade da mochila.':'Você voltou pelo elevador e guardou toda a mochila.'}<br>Habilidades, essências e melhorias continuam com você.</p><div class="result-stats"><div><small>GEMAS SALVAS</small><b>+${r.kept}</b></div><div><small>ANDAR</small><b>${r.floor}</b></div><div><small>SEQUÊNCIA</small><b>${r.peak}×</b></div></div><p>${r.lost?`${r.lost} gemas ficaram na caverna. `:''}Visite a árvore, combine habilidades e tente uma nova rota.</p><button class="primary" id="resultDone">Explorar minha base</button></div>`,'result');$('resultDone').onclick=closeDialog;}
function showTree(id=skillSelected){if(s.run)return;skillSelected=id;const k=SKILLS.find(k=>k.id===id)||SKILLS[0],owned=s.unlocked.includes(k.id),active=s.equipped.includes(k.id),positions={root:{x:50,y:4},...Object.fromEntries(SKILLS.map(k=>[k.id,k]))};const lines=SKILLS.flatMap(n=>n.parents.map(p=>`<path class="tree-line ${s.unlocked.includes(n.id)?'learned':''}" d="M ${positions[p].x} ${positions[p].y} L ${n.x} ${n.y}"/>`)).join('');
 openDialog('ÁRVORE DE ECOS · EVOLUÇÃO PERMANENTE',`<div class="tree-heading"><div><h2>Muitos caminhos. Seu próprio ritmo.</h2><p>Aprenda habilidades conectadas. Equipe até cinco e combine os três caminhos.</p></div><span>◇ ${fmt(s.bank)} gemas &nbsp; ✦ ${s.essence} essências</span></div><div class="tree-layout"><div class="tree-scroll"><div class="skill-tree"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${lines}</svg><div class="tree-root">◇</div>${['CADÊNCIA','IMPACTO','SIMBIOSE'].map((b,i)=>`<span class="branch-caption" style="left:${22+i*28}%">${b}</span>`).join('')}${SKILLS.map(n=>`<button class="tree-node ${s.unlocked.includes(n.id)?'owned':'locked'} ${s.equipped.includes(n.id)?'equipped':''} ${n.id===id?'selected':''}" style="left:${n.x}%;top:${n.y}%" data-skill="${n.id}" aria-label="${n.name}${s.equipped.includes(n.id)?', equipada':''}">${n.icon}<small>${n.name}</small></button>`).join('')}</div></div><aside class="skill-detail"><span class="detail-icon">${k.icon}</span><span class="detail-status">${active?'EQUIPADA NA SUA BUILD':owned?'HABILIDADE APRENDIDA':'NOVO CAMINHO'}</span><h3>${k.name}</h3><p>${k.desc}</p><div class="requirement">${k.parents[0]==='root'?'Conectada à raiz da árvore.':'Conexões necessárias:<br>'+k.parents.map(p=>`${s.unlocked.includes(p)?'✓':'○'} ${positions[p].name}`).join('<br>')}<br><br>${owned?'Troque suas habilidades na base, sem custo.':`Custo: ◇ ${k.cost} gemas + ✦ ${k.ess} essências`}</div><button class="primary" id="learnSkill" ${owned?(active||s.equipped.length<5?'':'disabled'):(canLearn(s,k)?'':'disabled')}>${owned?(active?'Retirar da build':s.equipped.length>=5?'5 espaços ocupados':'Equipar habilidade'):'Aprender habilidade'}</button><div class="build-note">${s.equipped.length}/5 espaços equipados.<br>Aprender é permanente. Sua build pode mudar a cada expedição.</div></aside></div>`,'tree');$('dialogBody').querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>showTree(b.dataset.skill));$('learnSkill').onclick=()=>{const done=owned?equip(s,k.id):learn(s,k.id);if(done){save();update();showTree(k.id);toast(owned?'Build atualizada.':'Um novo eco despertou.');}};
}
function showForge(){if(s.run)return;openDialog('FORJA DO REFÚGIO',`<h2>Sua única ferramenta. Infinitas possibilidades.</h2><p>A força da picareta é permanente. As habilidades da árvore mudam o que cada golpe pode fazer.</p><div class="shop-items"><div class="shop-item"><span class="shop-icon">⚒</span><div><h3>Picareta · nível ${s.level}</h3><p>Força atual: ${power(s)}. A próxima melhoria concede +1 de dano.</p></div><button class="primary" id="buyPick" ${s.bank<upgradeCost(s)||s.level>=12?'disabled':''}>${s.level>=12?'Nível máximo':`Melhorar · ◇ ${upgradeCost(s)}`}</button></div></div><p>◇ ${fmt(s.bank)} gemas guardadas. Só as gemas trazidas à base podem ser usadas aqui.</p>`,'forge');$('buyPick').onclick=()=>{if(purchaseUpgrade(s)){save();update();showForge();toast('Picareta reforçada. Vá um pouco mais fundo.');}};}
function showWell(){if(s.run)return;openDialog('FONTE DO PULSO',`<h2>Um fôlego a mais para continuar.</h2><p>A fonte guarda o pulso de suas expedições. Cada melhoria amplia a reserva de fôlego em 10 pontos.</p><div class="shop-items"><div class="shop-item"><span class="shop-icon">♡</span><div><h3>Reserva de fôlego · ${maxRhythm(s)}</h3><p>Melhoria permanente ${s.core}/6. Erros e criaturas continuam causando desgaste.</p></div><button class="primary" id="buyCore" ${s.bank<coreCost(s)||s.core>=6?'disabled':''}>${s.core>=6?'Fonte completa':`Ampliar · ◇ ${coreCost(s)}`}</button></div></div><p>◇ ${fmt(s.bank)} gemas guardadas.</p>`,'well');$('buyCore').onclick=()=>{if(purchaseCore(s)){save();update();showWell();toast('Sua reserva de fôlego aumentou.');}};}
function showLift(){if(s.run)return;const seal=SEALS[s.seals];openDialog('ELEVADOR DAS PROFUNDEZAS',`<h2>Vá além. Volte mais forte.</h2><p>Cada expedição começa no andar 1, com novas cavernas. Seus selos permitem alcançar novos biomas.</p><div class="milestones">${BIOMES.map((b,i)=>`<div class="milestone"><strong>${i<=s.seals?'✓':'○'} ${b.name}</strong><span>Andares ${i*4+1}–${i*4+4}</span></div>`).join('')}</div>${seal?`<div class="shop-items"><div class="shop-item"><span class="shop-icon">⌘</span><div><h3>${seal.name}</h3><p>Alcance o andar ${seal.floor} e retorne para abrir o próximo bioma.<br>Recorde: andar ${s.best}. Custo: ${seal.cost} gemas.</p></div><button class="primary" id="buySeal" ${s.best<seal.floor||s.bank<seal.cost?'disabled':''}>Construir selo</button></div></div>`:'<p>Os três selos estão construídos. O manto está ao seu alcance.</p>'}<button class="primary" id="liftStart">Iniciar expedição · até o andar ${depthLimit(s)} ↓</button>`,'lift');if(seal)$('buySeal').onclick=()=>{if(purchaseSeal(s)){save();update();showLift();toast('Novo bioma desbloqueado permanentemente!');}};$('liftStart').onclick=begin;}
function showHelp(){openDialog('GUIA DO EXPLORADOR',`<h2>Explore no ritmo. Volte mais forte.</h2><div class="help-grid"><div><strong>01 · Uma ação por batida</strong><p>Clique num alvo ou pressione espaço quando o losango cruza o centro. Erros e batidas sem ação quebram a sequência e drenam o fôlego.</p></div><div><strong>02 · Movimente-se e lute</strong><p>Clicar em um alvo faz um dash de até 5 casas e golpeia ao chegar perto. Espaço repete. WASD/setas esquivam. Chão vermelho anuncia um ataque: saia dele ou interrompa a criatura.</p></div><div><strong>03 · Faça escolhas</strong><p>Quartzo quebra rápido; prisma rende mais; geodo exige força; vital recupera fôlego. O Jardineiro faz novos cristais nascerem no ritmo.</p></div><div><strong>04 · Escolha quando voltar</strong><p>Reúna carga e mantenha a sequência exigida para abrir o elevador. Voltar salva 100% da mochila. Cair ou pedir resgate antes de abrir salva 50%.</p></div><div><strong>05 · Crie sua build</strong><p>Aprenda os nós conectados da árvore e equipe até 5. Combine cadência, impacto e simbiose. A picareta e a fonte também têm melhorias permanentes.</p></div><div><strong>06 · Uma descida por vez</strong><p>Andares 4, 8 e 12 são marcos. Volte à base e construa o selo do próximo bioma. Você recomeça no andar 1 com tudo que aprendeu.</p></div></div><p><kbd>ESPAÇO</kbd> atingir alvo &nbsp; <kbd>WASD / SETAS</kbd> esquivar &nbsp; <kbd>TAB</kbd> trocar alvo &nbsp; <kbd>P</kbd> pausar &nbsp; <kbd>E</kbd> extrair<br>Ative ♫ para ouvir. Trocar de aba pausa a expedição. O progresso fica salvo neste navegador.</p><button class="primary" id="helpDone">Entendi o pulso</button>`,'help');$('helpDone').onclick=closeDialog;}
function pause(){if(!s.run)return;paused=!paused;music.silence();$('pauseTitle').textContent='Respire. Seu ritmo espera.';$('pauseText').textContent='A expedição está pausada.';update();}
$('start').onclick=begin;$('descend').onclick=nextFloor;$('safeReturn').onclick=returnSafe;$('extract').onclick=extract;$('openTree').onclick=()=>showTree();$('openForge').onclick=showForge;$('openWell').onclick=showWell;$('help').onclick=showHelp;$('pause').onclick=pause;$('resume').onclick=()=>{paused=false;lastFrame=performance.now();update();$('world').focus({preventScroll:true});};
$('sound').onclick=async()=>{if(music.enabled){music.stop();$('sound').innerHTML='♫ <span>Som desligado</span>';$('sound').setAttribute('aria-label','Ativar música');}else if(await music.enable()){$('sound').innerHTML='♫ <span>Som ligado</span>';$('sound').setAttribute('aria-label','Desativar música');toast('Siga a batida. O centro da barra é seu pulso.');}};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use o modo de tela cheia do seu navegador.');}};
function screenTarget(point){if(!s.run)return null;return [...s.run.room.nodes,...s.run.room.enemies].filter(n=>n.hp>0).map(n=>{const p=project(n.x,n.y);return{n,d:Math.hypot(p.x-point.x,p.y-19-point.y)-(n.type==='enemy'?8:0)};}).sort((a,b)=>a.d-b.d).find(x=>x.d<36)?.n;}
$('world').addEventListener('pointermove',e=>{const p=world.pointer(e);hover=screenTarget(p)?.id??null;updateTip();});$('world').addEventListener('pointerleave',()=>{hover=null;updateTip();});
$('world').addEventListener('pointerdown',e=>{if(e.button!==0||$('dialog').open)return;$('world').focus({preventScroll:true});const p=world.pointer(e);if(!s.run){const h=HOTSPOTS.find(h=>Math.hypot(h.x-p.x,h.y-p.y)<110);world.target={x:p.x,y:p.y};if(h){clearTimeout(baseTimer);baseTimer=setTimeout(()=>({forge:showForge,tree:()=>showTree(),lift:showLift,well:showWell}[h.id]()),170);}return;}if(paused)return;if(s.run.room.cleared){const gate=project(18,2);if(Math.hypot(p.x-gate.x,p.y-gate.y)<75){if(s.run.floor<depthLimit(s)&&s.run.floor<16)nextFloor();else returnSafe();}return;}const target=screenTarget(p);if(target){selected=target.id;perform({type:'hit',id:target.id});}else{const tile=unproject(p.x,p.y);perform({type:'move',...tile});}});
document.addEventListener('keydown',e=>{if($('dialog').open||e.repeat)return;if(['KeyP','Escape'].includes(e.code)&&s.run){e.preventDefault();pause();return;}if(!s.run)return;const isGame=e.target===$('world')||e.target===document.body;if(!isGame)return;if(e.code==='Space'){e.preventDefault();perform({type:'hit',id:selected});}const dirs={KeyW:[0,-1],ArrowUp:[0,-1],KeyS:[0,1],ArrowDown:[0,1],KeyA:[-1,0],ArrowLeft:[-1,0],KeyD:[1,0],ArrowRight:[1,0]};if(dirs[e.code]){e.preventDefault();const [dx,dy]=dirs[e.code];perform({type:'dodge',dx,dy});}if(e.code==='Tab'&&!e.shiftKey){e.preventDefault();const targets=[...s.run.room.nodes,...s.run.room.enemies].filter(n=>n.hp>0);selected=targets[(targets.findIndex(n=>n.id===selected)+1)%targets.length]?.id;updateTip();}if(e.code==='KeyE')extract();});
document.addEventListener('visibilitychange',()=>{hidden=document.hidden;if(hidden&&s.run){paused=true;update();}music.silence();lastFrame=performance.now();save();});window.addEventListener('pagehide',save);new ResizeObserver(()=>world.resize()).observe($('stage'));
function frame(now){const wallDelta=Math.max(0,(now-lastFrame)/1000),dt=Math.min(.05,wallDelta);lastFrame=now;if(s.run&&!blocked()&&!s.run.room.cleared){elapsed+=wallDelta;const resolved=Math.floor(elapsed/BEAT-windowMs(s)/1000/BEAT);if(resolved>s.run.beat){while(s.run&&!s.run.room.cleared&&s.run.beat<resolved)tick(s,s.run.beat+1);if(!s.run)onReturn();else{processEvents();update();save();}}if(s.run&&feedbackTimer<elapsed)$('message').textContent=s.run?.beat<4?'Prepare-se: quatro batidas para entrar no ritmo.':'Clique em alvos · WASD para esquivar · espaço para continuar';}
 const phase=elapsed/BEAT;document.querySelectorAll('.note').forEach((n,i)=>n.style.left=`${50+(Math.floor(phase)+i-2-phase)*25}%`);$('beatLamp').style.opacity=Math.abs(phase-Math.round(phase))<.13?'1':'.2';world.draw(s,now/1000,dt,selected,hover,blocked());requestAnimationFrame(frame);}
setInterval(()=>{if(!blocked()&&!s.run?.room.cleared)music.update(s.run?elapsed+(performance.now()-lastFrame)/1000:performance.now()/1000,s.run?biomeIndex(s.run.floor):1);},25);
update();if(s.run){chooseNext();$('pauseTitle').textContent='Sua expedição está esperando.';$('pauseText').textContent='Continue de onde parou, no seu tempo.';}save();requestAnimationFrame(frame);
